const float kInv8 = 1.0 / 8.0;
const float kInv16 = 1.0 / 16.0;
const float kInv31 = 1.0 / 31.0;
const float kInv32 = 1.0 / 32.0;
const float kInv63 = 1.0 / 63.0;
const float kInv64 = 1.0 / 64.0;
const float kInv127 = 1.0 / 127.0;
const float kInv128 = 1.0 / 128.0;
const float kInv255 = 1.0 / 255.0;
const float kInv256 = 1.0 / 256.0;
const float kInv2047 = 1.0 / 2047.0;
const float kInv2048 = 1.0 / 2048.0;
const float kInv4095 = 1.0 / 4095.0;
const float kInv4096 = 1.0 / 4096.0;
const float kInv32767 = 1.0 / 32767.0;
const float kInv32768 = 1.0 / 32768.0;
const float kInv65535 = 1.0 / 65535.0;
const float kInv65536 = 1.0 / 65536.0;
